func FindCommitWithCheckpoint(ctx context.Context, repo, checkpointID string) (string, error) {
	// --all includes detached HEADs from every linked worktree because a
	// checkpoint commit can be reachable only from one of them. --ignore-missing
	// keeps an unrelated invalid worktree HEAD from breaking the whole lookup.
	out, err := run(ctx, repo, "git", "log", "--ignore-missing", "--all", "--format=%H", "-n", "1", "--grep=Entire-Checkpoint: "+checkpointID)
	if err != nil {
		return "", err
	}
	commit := strings.TrimSpace(out)
	if commit == "" {
		return "", fmt.Errorf("checkpoint %s has no associated commit in this repository", checkpointID)
	}
	return commit, nil
}

func AnalyzeCheckpoint(ctx context.Context, repo, checkpointID string) (Result, error) {
	if err := EnsureGitMetadataSafeForSubprocess(repo); err != nil {
		return Result{}, err
	}
	head, err := gitutil.FindCommitWithCheckpoint(ctx, repo, checkpointID)
	if err != nil {
		return Result{}, err
	}
	base, err := gitutil.FirstParent(ctx, repo, head)
	if err != nil {
		return Result{}, err
	}
	result, err := AnalyzeGitRange(ctx, repo, base, head, nil)
	if err != nil {
		return Result{}, err
	}
	result.Checkpoint = checkpointID
	return result, nil
}

func runCheckpoint(ctx context.Context, opts Options, args []string) error {
	flags, rest, err := parseCommonFlags(args)
	if err != nil {
		return err
	}
	if flags.Progress {
		return errors.New("checkpoint does not support --progress")
	}
	if flags.MaxSeconds >= 0 {
		return errors.New("checkpoint does not support --max-seconds")
	}
	if len(rest) != 1 {
		return errors.New("checkpoint requires exactly one checkpoint ID")
	}
	repo, err := resolveRepo(ctx, opts.Env, flags.Repo)
	if err != nil {
		return err
	}
	result, err := sem.AnalyzeCheckpoint(ctx, repo, rest[0])
	if err != nil {
		return err
	}
	return printResult(opts.Stdout, result, flags.JSON, opts.Version)
}

func firstGraphVerb(fields []string) (string, bool) {
	if len(fields) == 0 {
		return "", false
	}
	verb := strings.TrimLeft(shellWord(fields[0]), "-")
	switch verb {
	case "v":
		verb = "version"
	case "h":
		verb = "help"
	}
	if graphVerbs[verb] {
		return verb, true
	}
	return "", false
}

